const errors = [];
async function shot(name, vp, opts = {}) {
  const page = await browser.newPage({ viewport: vp, deviceScaleFactor: 1, reducedMotion: opts.reduced ? 'reduce' : 'no-preference' });
  page.on('pageerror', e => errors.push(name + ': ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push(name + ': ' + m.text()); });
  await page.goto(url);
  await page.waitForTimeout(1500);
  if (opts.moves) { for (const [x,y] of opts.moves) { await page.mouse.move(x,y,{steps:8}); } await page.waitForTimeout(opts.wait||400); }
  if (opts.click) { await page.mouse.click(...opts.click); await page.waitForTimeout(500); }
  await page.screenshot({ path: `<TMP>/rshot/${name}.png` });
  await page.close();
}
await shot('desktop', { width: 1440, height: 900 });
await shot('mobile', { width: 390, height: 844 });
await shot('reduced', { width: 1280, height: 800 }, { reduced: true });
await shot('mouse', { width: 1440, height: 900 }, { moves: [[300,200],[1100,300],[800,420]], click: [760, 560] });
await browser.close();
console.log(errors.length ? errors.join('\n') : 'no errors');
EOF
